    {
      "@type": "Question",
      "name": "What is the difference between a DMF and a CEP?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "A Drug Master File is a confidential submission held by a regulator describing the process, accessed on your behalf through a letter of access. A CEP is issued by the EDQM confirming a specific manufacturer's substance can be controlled by the European Pharmacopoeia monograph, and it can be verified independently."
      }
    },
    {
      "@type": "Question",
      "name": "Is a typical certificate of analysis acceptable?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "No. A specimen or typical certificate proves the supplier produced a conforming batch at some point. Always request the certificate for the batch you are buying, and check the specification on it matches what you agreed."
      }
    },
    {
      "@type": "Question",
      "name": "What is a written confirmation?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "For APIs imported into the EU from certain third countries, a confirmation from the exporting country's authority that the manufacturing site meets standards equivalent to EU GMP."
      }
    }
  ]
